return ['domain'=>NULL,'plural-forms'=>'nplurals=6; plural=(n == 0) ? 0 : ((n == 1) ? 1 : ((n == 2) ? 2 : ((n % 100 >= 3 && n % 100 <= 10) ? 3 : ((n % 100 >= 11 && n % 100 <= 99) ? 4 : 5))));','language'=>'ary','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:52:58+00:00','po-revision-date'=>'2026-10-31T05:52:58+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'كيعمّر الترجمات لي ناقصين فالإضافات والقوالب لي ديجا مثبتين فالموقع ديالك.','Translations'=>'الترجمات','Babilim Settings'=>'إعدادات Babilim','Settings'=>'الإعدادات','You are not allowed to do this.'=>'ما عندكش الصلاحية باش دير هادشي.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'اختار عدد أقل ديال المكونات: الحد الأقصى هو %1$d عمليات فكل تشغيل (نتا ختارتي %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'هاد المكوّن ماكاينش مثبّت فهاد الموقع، عليه ما يمكنش تطلب ترجمة ليه.','Already installed.'=>'مثبّت ديجا.','Downloaded and installed.'=>'تحمّل وتثبّت.','Babilim has not been enabled for this site yet.'=>'Babilim باقي ما تفعّلاتش لهاد الموقع.','No build is available to download for this locale.'=>'ماكاينش شي إصدار متاح للتحميل لهاد اللغة.','Rolled back to the previous build.'=>'تراجعات للإصدار السابق.','Rolled back and reported.'=>'تراجعات وتبعت التقرير.','Rolled back, but the report could not be sent: %s'=>'تراجعات، ولكن ما قدراش يتصيفط التقرير: %s','Removed.'=>'تحيّد.','Translation requested.'=>'تطلبات الترجمة.','This component was already uploaded. Babilim is checking it now.'=>'هاد المكوّن تحمّل من قبل. Babilim كيتحقق منو دابا.','Upload cancelled.'=>'تلغى التحميل.','Upload complete — translation requested.'=>'كمل التحميل — تطلبات الترجمة.','This component does not declare a version number, so a translation cannot be requested for it.'=>'هاد المكوّن ماكيصرّحش برقم النسخة، عليه ما يمكنش تط